96	  activate(
97	    mesh: THREE.Mesh,
98	    texture: THREE.CanvasTexture,
99	    videoUrl: string,
100	    proj: WorkProjectItem,
101	    size: WorkCardSize,
102	    staticImage: HTMLImageElement | null,
