227	class WorksCameraMotionRuntime {
228	  private readonly _layout: WorkLayoutConstants;
229	  private readonly _camPadX: number;
230	  private readonly _camPadY: number;
231	  private _baseCamZ: number;
232	  private _isDragging = false;
233	  private _dragPrevious: WorksPointerSample = { x: 0, y: 0 };
234	  private _targetX = 0;
235	  private _targetY = 0;
236	  private _velocityX = 0;
237	  private _velocityY = 0;
238	  private _targetZ: number;
239	  private _dynClampMinX: number;
240	  private _dynClampMaxX: number;
241	  private _dynClampMinY: number;
242	  private _dynClampMaxY: number;
243	
244	  constructor(
245	    layout: WorkLayoutConstants,
246	    camPadX: number,
247	    camPadY: number,
248	    camZ: number,
249	  ) {
250	    this._layout = layout;
251	    this._camPadX = camPadX;
252	    this._camPadY = camPadY;
253	    this._baseCamZ = camZ;
254	    this._targetZ = camZ;
255	    this._dynClampMinX = -camPadX;
256	    this._dynClampMaxX = camPadX;
257	    this._dynClampMinY = -camPadY;
258	    this._dynClampMaxY = camPadY;
259	  }
260	
261	  setDynamicClamp(positions: ReadonlyArray<WorksScatterPosition>): void {
262	    if (positions.length === 0) {
263	      this._dynClampMinX = this._dynClampMaxX = 0;
264	      this._dynClampMinY = this._dynClampMaxY = 0;
265	      return;
266	    }
267	    const MARGIN = 8;
268	    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
269	    for (const p of positions) {
270	      if (p.x < minX) minX = p.x;
271	      if (p.x > maxX) maxX = p.x;
272	      if (p.y < minY) minY = p.y;
273	      if (p.y > maxY) maxY = p.y;
274	    }
275	    this._dynClampMinX = minX - MARGIN;
276	    this._dynClampMaxX = maxX + MARGIN;
277	    this._dynClampMinY = minY - MARGIN;
278	    this._dynClampMaxY = maxY + MARGIN;
279	  }
280	
281	  activateScatter(): void {
282	    this._targetZ = this._baseCamZ;
283	  }
284	
285	  setTargetPosition(targetX: number, targetY: number): void {
286	    this._targetX = targetX;
287	    this._targetY = targetY;
288	  }
289	
290	  setTargetZ(targetZ: number): void {
291	    this._targetZ = targetZ;
292	  }
293	
294	  readBaseCamZ(): number {
295	    return this._baseCamZ;
296	  }
297	
298	  setBaseCamZ(baseCamZ: number): void {
299	    this._baseCamZ = baseCamZ;
300	    this._targetZ = baseCamZ;
301	  }
302	
303	  primeFromCamera(camera: THREE.PerspectiveCamera): void {
304	    this._targetX = camera.position.x;
305	    this._targetY = camera.position.y;
306	    this._targetZ = camera.position.z;
307	  }
308	
309	  primeFromCameraPosition(targetX: number, targetY: number, targetZ: number): void {
310	    this._targetX = targetX;
311	    this._targetY = targetY;
312	    this._targetZ = targetZ;
313	  }
314	
315	  beginDrag(camera: THREE.Camera, pointer: WorksPointerSample): void {
316	    this._isDragging = true;
317	    this._dragPrevious = { ...pointer };
318	    this._velocityX = 0;
319	    this._velocityY = 0;
320	    this._targetX = camera.position.x;
321	    this._targetY = camera.position.y;
322	  }
323	
324	  endDrag(): void {
325	    this._isDragging = false;
326	  }
327	
328	  updateDrag(
329	    viewport: WorksViewportSnapshot,
330	    halfView: WorksHalfViewBounds,
331	    pointer: WorksPointerSample,
332	    velMultiplier = 1,
333	  ): void {
334	    if (!this._isDragging) return;
335	    const dx = pointer.x - this._dragPrevious.x;
336	    const dy = pointer.y - this._dragPrevious.y;
337	    this._targetX += (-dx * (halfView.hW * 2)) / viewport.width;
338	    this._targetY += (dy * (halfView.hH * 2)) / viewport.height;
339	    this._velocityX = ((-dx * (halfView.hW * 2)) / viewport.width) * 0.7 * velMultiplier;
340	    this._velocityY = ((dy * (halfView.hH * 2)) / viewport.height) * 0.7 * velMultiplier;
341	    this._targetX = Math.max(
342	      this._dynClampMinX + halfView.hW,
343	      Math.min(this._dynClampMaxX - halfView.hW, this._targetX),
344	    );
345	    this._targetY = Math.max(
346	      this._dynClampMinY + halfView.hH,
347	      Math.min(this._dynClampMaxY - halfView.hH, this._targetY),
348	    );
349	    this._dragPrevious = { ...pointer };
350	  }
351	
352	  updateFrame(camera: THREE.Camera, delta: number): void {
353	    if (this._isDragging) {
354	      const decay = Math.pow(this._layout.velDecay, delta * 60);
355	      this._velocityX *= decay;
356	      this._velocityY *= decay;
357	      this._targetX += this._velocityX * delta * 60;
358	      this._targetY += this._velocityY * delta * 60;
359	    }
360	    const camFactor = 1 - Math.pow(1 - this._layout.camLerp, delta * 60);
361	    camera.position.x += (this._targetX - camera.position.x) * camFactor;
362	    camera.position.y += (this._targetY - camera.position.y) * camFactor;
363	    const camZFactor = 1 - Math.pow(1 - this._layout.camZLerp, delta * 60);
364	    camera.position.z += (this._targetZ - camera.position.z) * camZFactor;
365	    camera.lookAt(camera.position.x, camera.position.y, 0);
366	  }
367	
368	  get isDragging(): boolean {
369	    return this._isDragging;
370	  }
371	}
