589	    if (this.activeCategory !== category) {
590	      this._filterPrevCategory = this.activeCategory;
591	      this._filterBlendStartMs = performance.now();
592	    }
593	    this.activeCategory = category;
594	    const scatterPositions = this.categoryScatterPositions;
595	    const nextPositions = [...this.scatterPositions];
596	    const nextInteractiveMeshes: THREE.Mesh[] = [];
597	    const visiblePositions: WorksScatterPosition[] = [];
598	    let visibleIndex = 0;
599	    for (let index = 0; index < this.meshes.length; index += 1) {
600	      const mesh = this.meshes[index];
601	      if (!mesh || !this.isMeshInCategory(mesh)) continue;
602	      nextInteractiveMeshes.push(mesh);
603	      const targetPosition = scatterPositions[visibleIndex] ?? this.scatterPositions[index];
604	      nextPositions[index] = targetPosition;
605	      visiblePositions.push(targetPosition);
606	      visibleIndex += 1;
607	    }
608	    this.targetPositions = nextPositions;
609	    this.interactiveMeshes = nextInteractiveMeshes;
610	    this._centerCameraOnVisiblePositions(visiblePositions);
611	    this.cameraMotionRuntime.setTargetZ(this.cameraMotionRuntime.readBaseCamZ());
