660	  update(delta: number): void {
661	    if (!this.camera || !this.scene) return;
662	    const camera = this.camera;
663	    this.cameraMotionRuntime.updateFrame(camera, delta);
664	
665	    // Hover video: activate / deactivate when hovered mesh changes
666	    if (this.hovered !== this._prevHovered) {
667	      if (this._prevHovered) this._hoverVideo.deactivate();
668	      if (this.hovered) {
669	        const userData = this.hovered.userData as WorkCardUserData;
670	        if (userData.proj.thumbnailVideo) {
671	          const material = this.hovered.material as THREE.MeshBasicMaterial;
672	          const texture = material.map;
673	          if (texture instanceof THREE.CanvasTexture) {
674	            this._hoverVideo.activate(
675	              this.hovered,
676	              texture,
677	              userData.proj.thumbnailVideo,
678	              userData.proj,
679	              this._cardSize,
680	              userData.loadedImage ?? null,
681	            );
682	          }
683	        }
684	      }
685	      this._prevHovered = this.hovered;
686	    }
687	    if (this._hoverVideo.isActive()) this._hoverVideo.drawFrame();
688	
689	    const positionFactor = 1 - Math.pow(1 - this.layout.positionLerp, delta * 60);
690	    const opacityFactor = 1 - Math.pow(1 - this.layout.opacityLerp, delta * 60);
691	    const scaleFactor = 1 - Math.pow(1 - this.layout.scaleLerp, delta * 60);
692	    const isGridView = this.viewMode === "grid";
693	    const hover =
694	      this.hovered && this.isMeshInCategory(this.hovered) ? this.hovered : null;
695	    const blendT =
696	      this._filterBlendStartMs > 0
697	        ? Math.min(
698	            1,
699	            (performance.now() - this._filterBlendStartMs) /
700	              WorksSceneManager._filterBlendMs,
701	          )
702	        : 1;
703	    const filterEase = 1 - Math.pow(1 - blendT, 3);
704	    for (let index = 0; index < this.meshes.length; index += 1) {
705	      const mesh = this.meshes[index];
706	      const target = this.targetPositions[index] ?? this.scatterPositions[index];
707	      const isActiveCategory = this.isMeshInCategory(mesh);
708	      const wasIn = this._meshIncludedInFilter(mesh, this._filterPrevCategory);
709	      const nowIn = isActiveCategory;
710	      let targetY = target.y;
711	      if (wasIn && !nowIn && blendT < 1) {
712	        targetY += (1 - filterEase) * 6.5;
713	      }
714	      if (!wasIn && nowIn && blendT < 1) {
715	        targetY -= (1 - filterEase) * 7.5;
716	      }
717	      mesh.position.x += (target.x - mesh.position.x) * positionFactor;
718	      mesh.position.y += (targetY - mesh.position.y) * positionFactor;
719	      mesh.position.z += (0 - mesh.position.z) * positionFactor;
720	      mesh.quaternion.copy(camera.quaternion);
721	      const opacityAnchor = isActiveCategory ? target : mesh.position;
722	      const distance = dist2d(
723	        camera.position.x,
724	        camera.position.y,
725	        opacityAnchor.x,
726	        opacityAnchor.y,
727	      );
728	      let targetOpacity = Math.max(0, Math.min(0.92, 1 - (distance - 8) * 0.025));
729	      if (!isActiveCategory) targetOpacity = 0;
730	      if (isActiveCategory && this.activeCategory !== null) {
731	        targetOpacity = Math.max(0.3, targetOpacity);
732	      }
733	      if (isGridView) targetOpacity = 0;
734	      if (hover) targetOpacity = hover === mesh ? 1 : targetOpacity * 0.55;
735	      if (nowIn && !wasIn) {
736	        targetOpacity *= filterEase;
737	      }
738	      const material = mesh.material as THREE.MeshBasicMaterial;
739	      material.opacity += (targetOpacity - material.opacity) * opacityFactor;
740	      const steadyScale = (hover === mesh ? 1.06 : 1) * this._cardScale;
741	      mesh.scale.x += (steadyScale - mesh.scale.x) * scaleFactor;
742	      mesh.scale.y += (steadyScale - mesh.scale.y) * scaleFactor;
743	    }
744	  }
