819	  private bindEvents(): void {
820	    const canvas = this.canvas;
821	    if (!canvas) return;
822	
823	    const onPointerMove = (event: PointerEvent): void => {
824	      const viewport = this.viewportRuntime.read();
825	      if (this.viewMode !== "scatter") {
826	        this.hovered = null;
827	        return;
828	      }
829	      if (!this.camera) return;
830	      if (this.activePointerId !== event.pointerId) {
831	        if (this.activePointerId === null) {
832	          this.hovered = this.hitRuntime.resolve(
833	            this.camera,
834	            viewport,
835	            { x: event.clientX, y: event.clientY },
836	            this.interactiveMeshes,
837	          );
838	        }
839	        return;
840	      }
841	      if (this.cameraMotionRuntime.isDragging) {
842	        if (
843	          !this.dragInteractionStarted &&
844	          Math.hypot(event.clientX - this.mouseDownX, event.clientY - this.mouseDownY) >=
845	            WorksSceneManager._dragStartThresholdPx
846	        ) {
847	          this.dragInteractionStarted = true;
848	          this.onInteractionStart?.();
849	        }
850	        this.cameraMotionRuntime.updateDrag(
851	          viewport,
852	          this.viewportRuntime.readHalfView(this.camera),
853	          { x: event.clientX, y: event.clientY },
854	          this._isTouchPointer ? 2.0 : 1.0,
855	        );
856	        this.hovered = null;
857	        return;
858	      }
859	      this.hovered = this.hitRuntime.resolve(
860	        this.camera,
861	        viewport,
862	        { x: event.clientX, y: event.clientY },
863	        this.interactiveMeshes,
864	      );
865	    };
866	    const onPointerDown = (event: PointerEvent): void => {
867	      if (this.viewMode !== "scatter" || !this.camera) return;
868	      if (event.button !== 0) return;
869	      this.mouseDownX = event.clientX;
870	      this.mouseDownY = event.clientY;
871	      this.dragInteractionStarted = false;
872	      this.activePointerId = event.pointerId;
873	      this._isTouchPointer = event.pointerType === "touch";
874	      this.mouseDownMesh = this.hitRuntime.resolve(
875	        this.camera,
876	        this.viewportRuntime.read(),
877	        { x: event.clientX, y: event.clientY },
878	        this.interactiveMeshes,
879	      );
880	      this.cameraMotionRuntime.beginDrag(this.camera, {
881	        x: event.clientX,
882	        y: event.clientY,
883	      });
884	      canvas.setPointerCapture(event.pointerId);
885	    };
886	    const onPointerUp = (event: PointerEvent): void => {
887	      if (this.activePointerId !== event.pointerId) return;
888	      if (
889	        this.viewMode === "scatter" &&
890	        this.mouseDownMesh &&
891	        this.isMeshInCategory(this.mouseDownMesh) &&
892	        Math.hypot(event.clientX - this.mouseDownX, event.clientY - this.mouseDownY) <
893	          WorksSceneManager._dragStartThresholdPx
894	      ) {
895	        const userData = this.mouseDownMesh.userData as WorkCardUserData;
896	        this.onSelect?.(userData.detailPath);
897	      }
898	      this._resetPointerInteraction(event.pointerId);
899	    };
900	    const onPointerCancel = (event: PointerEvent): void => {
901	      if (this.activePointerId !== event.pointerId) return;
902	      this._resetPointerInteraction(event.pointerId);
903	    };
904	    const onPointerLeave = (): void => {
905	      if (this.activePointerId !== null) return;
906	      this.hovered = null;
907	    };
908	    const onResize = (): void => {
909	      if (!this.camera || !this.renderer) return;
910	      const viewport = this.viewportRuntime.read();
911	      if (this.camera instanceof THREE.OrthographicCamera) {
912	        const halfHeight =
913	          Math.tan((this.config.camFov * Math.PI) / 360) * this.config.camZ;
914	        const halfWidth = halfHeight * (viewport.width / viewport.height);
915	        this.camera.left = -halfWidth;
916	        this.camera.right = halfWidth;
917	        this.camera.top = halfHeight;
918	        this.camera.bottom = -halfHeight;
919	        this.camera.updateProjectionMatrix();
920	      }
921	      this.renderer.setPixelRatio(viewport.dpr);
922	      this.renderer.setSize(viewport.width, viewport.height);
923	      const resizeScaleBase = viewport.width < 768 ? CARD_SCALE_MOBILE_BASE_WIDTH : CARD_SCALE_BASE_WIDTH;
924	      const nextCardScale = Math.min(1, viewport.width / resizeScaleBase);
925	      if (nextCardScale !== this._cardScale) {
926	        this._cardScale = nextCardScale;
927	        this._rebuildScatterPositions();
928	      }
929	      this.applyCategory(this.activeCategory);
930	    };
931	    canvas.addEventListener("pointermove", onPointerMove);
932	    canvas.addEventListener("pointerdown", onPointerDown);
933	    canvas.addEventListener("pointerup", onPointerUp);
934	    canvas.addEventListener("pointercancel", onPointerCancel);
935	    canvas.addEventListener("pointerleave", onPointerLeave);
936	    window.addEventListener("resize", onResize);
937	    this.cleanup.push(
938	      () => canvas.removeEventListener("pointermove", onPointerMove),
939	      () => canvas.removeEventListener("pointerdown", onPointerDown),
940	      () => canvas.removeEventListener("pointerup", onPointerUp),
941	      () => canvas.removeEventListener("pointercancel", onPointerCancel),
942	      () => canvas.removeEventListener("pointerleave", onPointerLeave),
943	      () => window.removeEventListener("resize", onResize),
944	    );
945	  }
