947	  private startLoop(): void {
948	    if (this.rafId !== null) return;
949	    if (!this.camera || !this.renderer || !this.scene) return;
950	    this.clock = new THREE.Clock();
951	    this.clock.start();
952	    const animate = (): void => {
953	      if (!this.camera || !this.renderer || !this.scene || !this.clock) {
954	        this.rafId = null;
