956	      }
957	      this.rafId = FrameScheduler.request(animate);
958	      const delta = Math.min(this.clock.getDelta(), MAX_DELTA_SECONDS);
959	      this.update(delta);
960	      this.renderer.render(this.scene, this.camera);
961	    };
962	    animate();
963	  }
