1003	  private _readVisiblePositionsCenter(
1004	    positions: ReadonlyArray<WorksScatterPosition>,
1005	  ): WorksScatterPosition {
1006	    if (positions.length === 0) {
1007	      return { x: 0, y: 0 };
1008	    }
1009	    let minX = positions[0]?.x ?? 0;
1010	    let maxX = minX;
1011	    let minY = positions[0]?.y ?? 0;
1012	    let maxY = minY;
1013	    for (let index = 1; index < positions.length; index += 1) {
1014	      const position = positions[index];
1015	      if (!position) continue;
1016	      minX = Math.min(minX, position.x);
1017	      maxX = Math.max(maxX, position.x);
1018	      minY = Math.min(minY, position.y);
1019	      maxY = Math.max(maxY, position.y);
1020	    }
1021	    return {
1022	      x: (minX + maxX) * 0.5,
1023	      y: (minY + maxY) * 0.5,
1024	    };
1025	  }
